60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        HttpHeaders headers = new HttpHeaders();
116	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
117	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
118	        owner.setTelephone(normalizedTelephone);
119	        owner.setEmail(normalizeEmail(owner.getEmail()));
120	        owner.setAddress(normalizeAddress(owner.getAddress()));
121	        validatePostcode(owner.getCity(), owner.getPostcode());
122	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
123	        if (effectiveRegistrationDate == null) {
124	            effectiveRegistrationDate = LocalDate.now();
125	        } else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
126	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
127	                "registrationDate must not be later than the current server date");
128	        }
129	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
130	        owner.setRegistrationDate(effectiveRegistrationDate);
131	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
132	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
133	                "the maximum number of owners that may be created today has been reached");
134	        }
135	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
136	        if (sharesHousehold) {
137	            this.clinicService.assignHousehold(owner);
138	        }
139	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
140	            throw new ResponseStatusException(HttpStatus.CONFLICT,
141	                "an owner with the same identity already exists");
142	        }
143	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
144	            throw new ResponseStatusException(HttpStatus.CONFLICT,
145	                "city has reached its maximum number of owners");
146	        }
147	        owner.setCustomerCode(customerCodeFor(owner));
148	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
149	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
150	        owner.setBulkSignupWarning(
151	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
152	        this.clinicService.saveOwner(owner);
153	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
154	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
155	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
156	            ownerDto.getMembershipLevel());
157	        headers.setLocation(UriComponentsBuilder.newInstance()
158	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
159	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
165	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
166	        if (currentOwner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        currentOwner.setAddress(ownerFieldsDto.getAddress());
170	        currentOwner.setCity(ownerFieldsDto.getCity());
171	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
172	        currentOwner.setLastName(ownerFieldsDto.getLastName());
173	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
174	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
175	        this.clinicService.saveOwner(currentOwner);
176	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Transactional
181	    @Override
182	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        this.clinicService.deleteOwner(owner);
188	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
194	        Owner owner = this.clinicService.findOwnerById(ownerId);
195	        if (owner == null) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        HttpHeaders headers = new HttpHeaders();
199	        Pet pet = petMapper.toPet(petFieldsDto);
200	        owner.setId(ownerId);
201	        pet.setOwner(owner);
202	        pet.getType().setName(null);
203	        this.clinicService.savePet(pet);
204	        PetDto petDto = petMapper.toPetDto(pet);
205	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
