222	            }
223	        }
224	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
230	        HttpHeaders headers = new HttpHeaders();
231	        Visit visit = visitMapper.toVisit(visitFieldsDto);
232	        Pet pet = new Pet();
233	        pet.setId(petId);
234	        visit.setPet(pet);
235	        this.clinicService.saveVisit(visit);
236	        VisitDto visitDto = visitMapper.toVisitDto(visit);
237	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
238	            .buildAndExpand(visit.getId()).toUri());
239	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
240	    }
241	
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
246	        Owner owner = this.clinicService.findOwnerById(ownerId);
247	        if (owner != null) {
248	            Pet pet = owner.getPet(petId);
249	            if (pet != null) {
250	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
251	            }
252	        }
253	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	    }
255	
256	    /**
257	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
258	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
259	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
260	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
261	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
262	     * sequence number, so it is a stable function of the owner's region and telephone/last-name
263	     * identity rather than of creation order.
264	     *
265	     * @param owner the owner being created, with its telephone already normalized to E.164 form
266	     * @return the assigned customer code
267	     */
268	    private String customerCodeFor(Owner owner) {
269	        String region = ownerMapper.regionOf(owner);
270	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName()).substring(0, 8);
271	        return region + "-" + hash8;
272	    }
273	
274	    /**
275	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as an
276	     * upper-case hex string.
277	     *
278	     * @param value the string to hash
279	     * @return the full SHA-256 digest as upper-case hex
280	     */
281	    private static String sha256UpperHex(String value) {
282	        try {
283	            byte[] digest = MessageDigest.getInstance("SHA-256")
284	                .digest(value.getBytes(StandardCharsets.UTF_8));
285	            StringBuilder sb = new StringBuilder(digest.length * 2);
286	            for (byte b : digest) {
287	                sb.append(String.format("%02X", b));
288	            }
289	            return sb.toString();
290	        } catch (NoSuchAlgorithmException ex) {
291	            throw new IllegalStateException("SHA-256 not available", ex);
292	        }
293	    }
294	
295	    /**
296	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
297	     * owner's city already contains this many owners.
298	     */
299	    private static final int CITY_CAPACITY = 50;
300	
301	    /**
302	     * The maximum number of owners that may be created on a single day. A create is rejected with
303	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
304	     * {@code registrationDate}.
305	     */
306	    private static final int DAILY_CREATE_LIMIT = 100;
307	
308	    /**
309	     * The number of owners that must already have been created for the current day before a new
310	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
311	     * owners already carry today's {@code registrationDate}.
312	     */
313	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
314	
315	    /**
316	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
317	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
318	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
319	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
320	     * falls on a business day.
321	     *
322	     * @param date the effective registration date
323	     * @return the same date when it is a weekday, otherwise the following Monday
324	     */
325	    private static LocalDate rollToBusinessDay(LocalDate date) {
326	        return switch (date.getDayOfWeek()) {
327	            case SATURDAY -> date.plusDays(2);
328	            case SUNDAY -> date.plusDays(1);
329	            default -> date;
330	        };
331	    }
332	
333	    /**
334	     * Counts the existing owners whose {@code registrationDate} equals the given (already
335	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
336	     * business day. Called before a new owner is saved, so the returned value reflects the number of
337	     * owners created for that day prior to this create.
338	     *
339	     * @param date the adjusted business-day registration date to count against
340	     * @return the number of existing owners registered on that date
341	     */
342	    private int countOwnersRegisteredOn(LocalDate date) {
343	        return (int) this.clinicService.findAllOwners().stream()
344	            .filter(existing -> date.equals(existing.getRegistrationDate()))
345	            .count();
346	    }
347	
348	    /**
349	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
350	     *
351	     * @param city the city to count owners for
352	     * @return the number of existing owners in that city
353	     */
354	    private int countOwnersInCity(String city) {
355	        return (int) this.clinicService.findAllOwners().stream()
356	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
357	            .count();
358	    }
359	
360	    /**
361	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
362	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
363	     *
364	     * @param customerCode     the owner's assigned customer code
365	     * @param registrationDate the owner's registration date
366	     * @return the assigned membership number
367	     */
368	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
369	        String yy = String.format("%02d", registrationDate.getYear() % 100);
370	        return String.format("%s-M%s", customerCode, yy);
371	    }
372	
373	    /**
374	     * Counts the existing owners that already share the given first name and last name, comparing
375	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
376	     * the number of namesakes that existed prior to this create.
377	     *
378	     * @param firstName the new owner's first name
379	     * @param lastName  the new owner's last name
380	     * @return the number of existing owners with the same first and last name
381	     */
382	    private int countNamesakes(String firstName, String lastName) {
383	        int count = 0;
384	        for (Owner existing : this.clinicService.findAllOwners()) {
385	            if (firstName.equalsIgnoreCase(existing.getFirstName())
386	                && lastName.equalsIgnoreCase(existing.getLastName())) {
387	                count++;
388	            }
389	        }
390	        return count;
391	    }
392	
393	    /**
394	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
395	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
396	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
397	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
398	     * string is what gets stored and returned.
399	     *
400	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
401	     *
402	     * <p>Once in E.164 form the national-number length is validated against the country code: a
403	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
404	     * number exactly 10 (see {@link #COUNTRY_NATIONAL_LENGTHS}). Country codes without a configured
405	     * rule are accepted on the general 8-to-15 digit length alone.
406	     *
407	     * @param telephone the raw telephone value supplied by the client
408	     * @return the normalized E.164 telephone number
409	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
410	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
411	     *                                 after the {@code '+'}, or the wrong national-number length for
412	     *                                 its country code)
413	     */
414	    private static String normalizeTelephone(String telephone) {
415	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
416	        String digits;
417	        if (cleaned.startsWith("+")) {
418	            digits = cleaned.substring(1);
419	        } else {
420	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
421	            digits = "61" + national;
422	        }
423	        if (!digits.matches("[0-9]{8,15}")) {
424	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
425	                "telephone could not be normalized to a valid E.164 number");
426	        }
427	        validateNationalNumberLength(digits);
428	        return "+" + digits;
429	    }
430	
431	    /**
432	     * International dialling codes mapped to the exact number of national (subscriber) digits an
433	     * E.164 number for that country must carry: {@code +61} (Australia) requires 9 national digits
434	     * and {@code +1} (NANP) requires 10. Country codes absent from this map have no length rule.
435	     */
436	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
437	
438	    /**
439	     * Validates the national-number length of an E.164 number (its digits, without the leading
440	     * {@code '+'}) against its country code. The longest configured dialling code that prefixes the
441	     * number selects the rule; if none is configured the number passes (only the general 8-to-15
442	     * digit rule applies).
443	     *
444	     * @param digits the E.164 digits without the leading {@code '+'}
445	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
446	     *                                 digits does not match the country code's required length
447	     */
448	    private static void validateNationalNumberLength(String digits) {
449	        COUNTRY_NATIONAL_LENGTHS.keySet().stream()
450	            .filter(digits::startsWith)
451	            .max(Comparator.comparingInt(String::length))
452	            .ifPresent(code -> {
453	                int nationalLength = digits.length() - code.length();
454	                if (nationalLength != COUNTRY_NATIONAL_LENGTHS.get(code)) {
455	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
456	                        "telephone must have " + COUNTRY_NATIONAL_LENGTHS.get(code)
457	                            + " national digits for country code +" + code);
458	                }
459	            });
460	    }
461	
462	    /**
463	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
464	     * containing at least one dot, none of the three sections containing whitespace or an
465	     * additional {@code @}.
466	     */
467	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
468	
469	    /**
470	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
471	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
472	     * value is then stored and returned lower-cased.
473	     *
474	     * @param email the raw email value supplied by the client, possibly {@code null}
475	     * @return the lower-cased email, or {@code null} when none was supplied
476	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
477	     *                                 is not a syntactically valid address
478	     */
479	    private static String normalizeEmail(String email) {
480	        if (email == null) {
481	            return null;
482	        }
483	        if (!EMAIL_PATTERN.matcher(email).matches()) {
484	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
485	                "email must be a syntactically valid address");
486	        }
487	        return email.toLowerCase(Locale.ROOT);
488	    }
489	
490	    /**
491	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
492	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
493	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
494	     */
495	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
496	        "NSW", new int[] {2000, 2099},
497	        "VIC", new int[] {3000, 3099},
498	        "QLD", new int[] {4000, 4099});
499	
500	    /**
501	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
502	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
503	     * four-digit format is enforced by request validation; here the value is range-checked: when the
504	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
505	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
506	     * accepts any four-digit postcode.
507	     *
508	     * @param city     the owner's city
509	     * @param postcode the owner's postcode, possibly {@code null}
510	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
511	     *                                 out of range for the city's region
512	     */
513	    private static void validatePostcode(String city, String postcode) {
514	        if (postcode == null) {
515	            return;
516	        }
517	        String region = OwnerMapper.CITY_REGION.get(city);
518	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
519	        if (range == null) {
520	            return;
521	        }
522	        int value = Integer.parseInt(postcode);
523	        if (value < range[0] || value > range[1]) {
524	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
525	                "postcode " + postcode + " is not valid for region " + region);
526	        }
527	    }
528	
529	    /**
530	     * Common street-type abbreviations expanded to their full word during address normalization.
531	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
532	     */
533	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
534	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
535	
536	    /**
537	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
538	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
539	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
540	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
541	     * address comparison (household duplicate detection and the shared household id).
542	     *
543	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
544	     *
545	     * @param address the raw address supplied by the client, possibly {@code null}
546	     * @return the normalized address
547	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
548	     *                                 after normalization (required field)
549	     */
550	    private static String normalizeAddress(String address) {
551	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
552	        if (collapsed.isEmpty()) {
553	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
554	                "address must not be blank");
555	        }
556	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
557	        StringBuilder normalized = new StringBuilder();
558	        for (int i = 0; i < tokens.length; i++) {
559	            if (i > 0) {
560	                normalized.append(' ');
561	            }
562	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
563	        }
564	        return normalized.toString();
565	    }
566	
567	    /**
568	     * Determines whether the given whole identity key already belongs to any owner other than the
569	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
570	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
571	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
572	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
573	     *
574	     * @param identityKey the identity key to look for
575	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
576	     * @return {@code true} if another owner already has the same identity key
577	     */
578	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
579	        for (Owner existing : this.clinicService.findAllOwners()) {
580	            if (excludeId != null && excludeId.equals(existing.getId())) {
581	                continue;
582	            }
583	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
584	                return true;
585	            }
586	        }
587	        return false;
588	    }
589	
590	}
